"""Actual Chrome interaction and layout acceptance, outside benchmark timing."""
import os
import json,re,subprocess,sys,tempfile
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[2];OUT=(ROOT/os.environ.get('REVERSI_PROFILE_RUN','.local-research/profiling-m4-20261030')).resolve()
def main():
    with tempfile.TemporaryDirectory() as temp:
        server=subprocess.Popen([sys.executable,str(ROOT/'launch.py'),'--no-browser','--port','0','--http-log',str(Path(temp)/'http.log')],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
        try:
            base=re.search(r'http://127\.0\.0\.1:\d+/',server.stdout.readline()).group();checks=[];errors=[];remote=[]
            with sync_playwright() as pw:
                browser=pw.chromium.launch(channel='chrome');page=browser.new_page(viewport={'width':1440,'height':1100},device_scale_factor=1);page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:remote.append(r.url) if r.url.startswith(('http:','https:')) and not r.url.startswith(base) else None)
                page.goto(base+'profiling/');page.wait_for_function('()=>document.querySelector("#status").textContent.includes("hardware-ip")');assert page.locator('h2').inner_text()=='Runtime is the performance result.';assert page.locator('#view svg circle').count()>30;checks.append('committed benchmark trials, legends and uncertainty load')
                page.screenshot(path=str(OUT/'explorer-benchmarks.png'),full_page=True)
                def tab(name):page.locator(f'#tabs button[data-view="{name}"]').click()
                def profile(value,method):page.select_option('#profile',value);page.wait_for_function('(method)=>document.querySelector("#status").textContent.includes(method)',arg=method)
                tab('instructions');assert page.locator('#hot-table tbody tr').count()>5;page.fill('#search','lastEmpties');assert page.locator('#hot-table tbody tr').count()>0;page.locator('#hot-table tbody tr').first.click();assert 'assembly' not in page.locator('.detail').inner_text().lower() or page.locator('.detail pre').count();assert page.locator('.detail pre').count()==1;page.locator('[data-sort="count"]').click();page.fill('#search','no-such-reversi-symbol');assert page.locator('#hot-table tbody tr').count()==0;page.fill('#search','');page.select_option('#level','function');assert page.locator('#hot-table tbody tr').count()>0;checks.append('instruction search/sort/grouping and source/assembly detail')
                tab('sunburst');paths=page.locator('#view svg path');assert paths.count()>3;point=paths.first.evaluate('p=>{const q=p.getPointAtLength(p.getTotalLength()*.2);const t=new DOMPoint(310+(q.x-310)*.98,300+(q.y-300)*.98).matrixTransform(p.getScreenCTM());return {x:t.x,y:t.y};}');page.mouse.move(point['x'],point['y']);assert page.locator('#tooltip').is_visible();assert 'samples' in page.locator('#tooltip').inner_text();page.mouse.click(point['x'],point['y']);assert page.get_by_role('button',name='Up',exact=True).is_enabled();page.get_by_role('button',name='Reset zoom').click();page.screenshot(path=str(OUT/'explorer-sunburst.png'),full_page=True);checks.append('address sunburst hover, containment zoom and reset')
                tab('stacks');assert 'no calling stacks' in page.locator('#view').inner_text();checks.append('IP dataset does not fabricate a call graph')
                profile('exact-P-after-stacks-1000000-0','hardware-raw-stacks');tab('stacks');rects=page.locator('.chartwrap svg rect');assert rects.count()>10;rects.nth(1).hover();assert 'inclusive' in page.locator('#tooltip').inner_text() and 'self' in page.locator('#tooltip').inner_text();rects.nth(1).click();assert page.get_by_role('button',name='Up',exact=True).is_enabled();page.get_by_role('button',name='Reset zoom').click();page.get_by_role('searchbox',name='Search calling stacks').fill('lastEmpties');assert page.locator('svg .hit').count()>0
                with page.expect_download() as d:page.get_by_role('button',name='Export to Speedscope').click()
                p=Path(temp)/'export.json';d.value.save_as(p);s=json.loads(p.read_text());assert s['profiles'][0]['unit']=='none';assert len(s['profiles'][0]['samples'])>100;page.screenshot(path=str(OUT/'explorer-stacks.png'),full_page=True);checks.append('real stack icicle search/zoom, self/inclusive tooltip and weighted Speedscope export')
                tab('differential');page.wait_for_selector('#diff-table tbody tr');assert page.locator('#view .card').count()==3;page.select_option('#diff-level','paths');page.fill('#diff-search','lastEmpties');assert page.locator('#diff-table tbody tr').count()>0;checks.append('matched differential calling paths with unprofiled runtime')
                tab('timeline');canvas=page.locator('canvas');assert canvas.count()==1;canvas.hover();page.mouse.wheel(0,-300);assert 'ms from FixedWork' in page.locator('#view pre').inner_text();canvas.hover(position={'x':400,'y':80});assert 'Captured at' in page.locator('#view pre').inner_text();page.get_by_role('button',name='Reset time zoom').click();checks.append('real chronological sample marks, time zoom and full-stack hover')
                profile('exact-P-after-ip-1000000-0','hardware-ip');tab('differential');page.wait_for_selector('#diff-table');page.wait_for_function('()=>document.querySelector("#diff-level option[value=paths]")?.disabled===true');checks.append('IP comparison does not invent calling paths')
                page.evaluate('''()=>{const p=document.querySelector('#profile');p.value='exact-P-after-cpu-high-0';p.dispatchEvent(new Event('change'));p.value='exact-P-after-ip-1000000-0';p.dispatchEvent(new Event('change'));}''');page.wait_for_function('()=>document.querySelector("#status").textContent.includes("hardware-ip")');tab('instructions');assert 'empty stack requirements' in page.locator('#view').inner_text();checks.append('rapid profile changes cannot publish a stale capture under new labels')
                with page.expect_download() as d:page.get_by_role('button',name='Download records').click()
                p=Path(temp)/'actual.json';d.value.save_as(p);original=json.loads(p.read_text());assert 'stacks' not in original
                for bad in [{'version':999},{**original,'accounting':{**original['accounting'],'weight':-1}}]:
                    page.locator('#import').set_input_files({'name':'malformed.json','mimeType':'application/json','buffer':json.dumps(bad).encode()});assert page.locator('#error').is_visible()
                checks.append('malformed imports surface errors without navigation or execution')
                noTime={**original,'samples':[[None,*s[1:]] for s in original['samples']]};noTime.pop('timestamps',None);page.locator('#import').set_input_files({'name':'actual-without-timestamps.json','mimeType':'application/json','buffer':json.dumps(noTime).encode()});tab('timeline');assert 'cannot be constructed' in page.locator('#view').inner_text();assert page.locator('canvas').count()==0;checks.append('timestamp-free records cannot acquire a fabricated timeline')
                page.reload();page.wait_for_function('()=>document.querySelector("#status").textContent.includes("hardware-ip")');page.set_viewport_size({'width':790,'height':1050});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+1');page.screenshot(path=str(OUT/'explorer-mobile.png'),full_page=True);checks.append('narrow layout and clean reload')
                assert not errors,errors;assert not remote,remote;receipt={'passed':True,'browser':browser.version,'checks':checks,'pageErrors':errors,'externalRequests':remote,'urlPath':'/profiling/','screenshots':'ignored local investigation directory'};(OUT/'browser-qualification.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt,indent=2));browser.close()
        finally:server.terminate();server.communicate(timeout=5)
if __name__=='__main__':main()
